# =============================================================================
# Auto-generated by VAE Studio — structural decoder for the VAE-NLME
# engine. Per individual: analytic PK concentrations + (optionally) an ODE for
# further dynamics (e.g. an augmented Neural-ODE), mapped to observations via
# `observe`. ζ = individual parameters (theta), z_lat = latent conditioning.
#
# Speed is the goal: predefined PK models are solved in CLOSED FORM (no ODE);
# remaining ODEs use in-place f! + StaticArrays and are meant to be driven by an
# EnsembleProblem (threaded) across patients. Encoder/ELBO/training are M2.
# =============================================================================
module StructuralDecoder

using ChainRulesCore
import ..VAEEngine: pk_layout, pk_coefrate, pk_superpose, pk_predict

const PARAM_NAMES = (:ka_C, :Cl_C, :V1_C, :Q_C, :V2_C)
const LATENT_NAMES = ()
const STATE_NAMES = ()
const N_STATES = 0
const HAS_RATE_DOSE = false
const OBS_NAMES = ("Conc",)
const AI_STATES = ()

# C(t): 2-cmt · oral (1st-order abs) · (ka, V1, Cl, Q, V2) — closed-form (superposition over doses).
function pkconc_C(t, theta, dose)
    @inbounds begin
        ka = theta[1]
        Cl = theta[2]
        V1 = theta[3]
        Q = theta[4]
        V2 = theta[5]
        ke = Cl / V1
        k12 = Q / V1
        k21 = Q / V2
        s = ke + k12 + k21
        disc = sqrt(max(s * s - 4 * k21 * ke, zero(s)))
        alpha = 0.5 * (s + disc)
        beta = 0.5 * (s - disc)
        acc = 0.0
        for r in axes(dose, 1)
            td = dose[r, 1]; amt = dose[r, 2]
            if amt != 0.0 && t >= td
                dt = t - td
                acc += amt * ka / V1 * ((k21 - alpha) / ((ka - alpha) * (beta - alpha)) * exp(-alpha * dt) + (k21 - beta) / ((ka - beta) * (alpha - beta)) * exp(-beta * dt) + (k21 - ka) / ((alpha - ka) * (beta - ka)) * exp(-ka * dt))
            end
        end
        return acc
    end
end

# C: Parameterspalte eines Individuums -> [coef_j, rate_j, …, dur, F] (skalar).
@inline function pk_cr_C!(o, p)
    ka = p[1]
    Cl = p[2]
    V1 = p[3]
    Q = p[4]
    V2 = p[5]
    ke = Cl / V1
    k12 = Q / V1
    k21 = Q / V2
    s = ke + k12 + k21
    disc = sqrt(max(s * s - 4 * k21 * ke, zero(s)))
    alpha = 0.5 * (s + disc)
    beta = 0.5 * (s - disc)
    o[1] = ka * (k21 - alpha) / (V1 * (ka - alpha) * (beta - alpha))
    o[2] = alpha
    o[3] = ka * (k21 - beta) / (V1 * (ka - beta) * (alpha - beta))
    o[4] = beta
    o[5] = ka * (k21 - ka) / (V1 * (alpha - ka) * (beta - ka))
    o[6] = ka
    o[7] = 0.0
    o[8] = 1.0
    return o
end

# batched C(t): (n_params,N) × dose × times -> (N, n_obs).
function pkconc_batch_C(theta, dose, times)
    td  = view(dose, :, :, 1)   # (N, nd)
    amt = view(dose, :, :, 2)   # (N, nd)
    return pk_predict(pk_cr_C!, 3, theta, td, amt, times)
end

# Batched predictions (N, n_obs, n_obs_types) in OBS_NAMES order.
function predict_batch(theta, dose, times)
    N = size(theta, 2); no = size(times, 2)
    t = times                                   # (N, no) — Zeit je Punkt
    C = pkconc_batch_C(theta, dose, times)
    ka_C = reshape(view(theta, 1, :), N, 1)
    Cl_C = reshape(view(theta, 2, :), N, 1)
    V1_C = reshape(view(theta, 3, :), N, 1)
    Q_C = reshape(view(theta, 4, :), N, 1)
    V2_C = reshape(view(theta, 5, :), N, 1)
    zed = zeros(eltype(theta), N, no)          # erzwingt (N, no) je Output
    o1 = (@. (C)) .+ zed
    return reshape(o1, N, no, 1)
end

# Predicted observations at (u, t) in OBS_NAMES order. p = (theta, latent, ..).
function observe(u, p, t)
    theta = p.theta; latent = p.latent; dose = p.dose
    @inbounds begin
        ka_C = theta[1]
        Cl_C = theta[2]
        V1_C = theta[3]
        Q_C = theta[4]
        V2_C = theta[5]
        C = pkconc_C(t, theta, dose)
        return (C,)
    end
end

const ALLVAR_NAMES = ("C",)
# Every model quantity at (u, t) in ALLVAR_NAMES order — for the results plots.
function allvars(u, p, t)
    theta = p.theta; latent = p.latent; dose = p.dose
    @inbounds begin
        ka_C = theta[1]
        Cl_C = theta[2]
        V1_C = theta[3]
        Q_C = theta[4]
        V2_C = theta[5]
        C = pkconc_C(t, theta, dose)
        return (C,)
    end
end

# Predict observations at `times` for one individual.
function predict(theta, latent, nn, dose, times)
    p = (theta = theta, latent = latent, nn = nn, dose = dose)
    return [observe(nothing, p, tt) for tt in times]  # analytic PK, no ODE
end

end # module StructuralDecoder
